                } else if (t >= 1000 && t < 2000) {
                    toastMessage = '【网络环境一般】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他源站或切换网络环境\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛';
                } else if (t >= 2000 && t < 5000) {
                    toastMessage = '【网络环境堪忧】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他源站或切换网络环境\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛';
                }
                java.longToast(toastMessage);
                Packages.java.lang.Thread.sleep(400);
                //处理搜索及缓存
   let urli = `${this.getUrl()}search.html?q=${encodeURI(key)}&f=tag&sort=relevance&p=${page}&serialize=`;
                //java.log(urli);
   let ss = java.get(urli, { 'user-agent': ua });
                this.cache.put('urlss', ss.body());
                break;
            } else {
                java.longToast('【访问失败提示】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️源站已失效(可能被墙)♣️\n┋┋\n请更新网址/切换源站/切换网络环境\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
